const sectors=[
['۰۱','⚒','تأمین ماشین‌آلات و تجهیزات صنایع معدنی','MINING & EQUIPMENT','تأمین ماشین‌آلات معادن و تجهیزات فرآوری مواد معدنی، شامل خطوط خردایش و دانه‌بندی، سنگ‌شکن، ماسه‌ساز، سرند و نوار نقاله، متناسب با نیازهای فنی و عملیاتی معادن و واحدهای صنعتی.'],
['۰۲','⇄','حمل‌ونقل و لجستیک بین‌المللی','TRANSPORT & LOGISTICS','ارائه خدمات حمل جاده‌ای، دریایی، هوایی و ریلی، ترانزیت، فورواردینگ و مدیریت زنجیره تأمین؛ با تمرکز بر حمل‌ونقل چندوجهی، بهینه‌سازی مسیرها و تسهیل جابه‌جایی محموله‌های صنعتی و تجاری.'],
['۰۳','◎','بازرگانی، صادرات و واردات','INTERNATIONAL TRADE','صادرات و واردات کالا، تأمین مواد اولیه و محصولات صنعتی، شناسایی بازارهای هدف و توسعه ارتباطات تجاری میان تولیدکنندگان، تأمین‌کنندگان و خریداران در بازارهای منطقه‌ای و جهانی.'],
['۰۴','ϟ','انرژی، نفت، گاز و پتروشیمی','ENERGY & PETROCHEMICALS','تأمین و تجارت فرآورده‌های نفتی، گاز، محصولات پتروشیمی و مواد اولیه صنایع انرژی، با هدف توسعه همکاری‌های تجاری و پیوند عرضه‌کنندگان با بازارهای مصرف.'],
['۰۵','▧','نساجی و منسوجات','TEXTILES & FABRICS','تأمین و تجارت انواع پارچه، منسوجات، مواد اولیه نساجی و ملزومات دکوراسیون داخلی و صنعت مبلمان، با تمرکز بر پاسخ‌گویی به نیاز مشتریان تجاری و توسعه بازار.'],
['۰۶','⌂','عمران، ساخت‌وساز و سرمایه‌گذاری ملکی','CONSTRUCTION & REAL ESTATE','توسعه پروژه‌های عمرانی و ساختمانی، مشارکت در ساخت، سرمایه‌گذاری، خریدوفروش و مدیریت املاک و مستغلات، با هدف شناسایی فرصت‌های اقتصادی و ایجاد ارزش افزوده پایدار.'],
['۰۷','♧','کشاورزی، کشت و صنعت و سرمایه‌گذاری','AGRICULTURE & AGRIBUSINESS','سرمایه‌گذاری، توسعه و مشارکت در طرح‌های زراعی، باغی و کشت و صنعت؛ راه‌اندازی واحدهای تولیدی، صنایع تبدیلی و تکمیلی، فرآوری و بسته‌بندی محصولات کشاورزی و غذایی و توسعه زنجیره تأمین و عرضه، با هدف بهینه‌سازی مصرف منابع، افزایش بهره‌وری و ایجاد ارزش افزوده در بازارهای داخلی و بین‌المللی.']
];
document.getElementById('sector-list').innerHTML=sectors.map((s,i)=>`<details class="sector" ${i===0?'open':''}><summary><span class="sector-num">${s[0]}</span><span class="sector-symbol" aria-hidden="true">${s[1]}</span><h3>${s[2]}</h3><span class="sector-en" dir="ltr">${s[3]}</span><span class="plus" aria-hidden="true">+</span></summary><p>${s[4]}</p></details>`).join('');
const menu=document.getElementById('menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'بستن منو':'باز کردن منو')});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','باز کردن منو')}});
document.getElementById('inquiry').addEventListener('submit',e=>{e.preventDefault();const text=`گروه بین‌المللی فرا\nدرخواست همکاری\n\nحوزه: ${document.getElementById('field').value}\n\n${document.getElementById('message').value}\n`;const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FARA-cooperation.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('form-status').textContent='خلاصه درخواست آماده شد. این درخواست به شرکت ارسال نشده است.'});
